import os
tot=0
for root,dirs,files in os.walk('.'):
    if '.git' in dirs: dirs.remove('.git')
    for f in files:
        p=os.path.join(root,f)
        try: t=open(p,errors='replace').read()
        except: continue
        c=t.count('TODO')
        if c: print(p,c); tot+=c
print('total',tot)
